const update = $json;
const message = update.message ?? update.edited_message ?? update.channel_post;
if (!message) {
  throw new Error('This workflow only accepts Telegram message updates.');
}

const selectMedia = (source) => {
  if (!source || typeof source !== 'object') {
    return { mediaType: 'none', media: null };
  }
  const photos = Array.isArray(source.photo) ? source.photo : [];
  const candidates = [
    ['voice', source.voice],
    ['audio', source.audio],
    ['image', photos.length ? photos[photos.length - 1] : null],
    ['document', source.document],
    ['video', source.video],
  ];
  const selected = candidates.find(([, candidate]) => candidate?.file_id);
  return selected
    ? { mediaType: selected[0], media: selected[1] }
    : { mediaType: 'none', media: null };
};

const chatId = String(message.chat?.id ?? '');
const messageId = String(message.message_id ?? '');
if (!chatId || !messageId) {
  throw new Error('Telegram update is missing chat.id or message_id.');
}

const directSelection = selectMedia(message);
const repliedMessage = message.reply_to_message;
const replySelection = selectMedia(repliedMessage);
const usesReplyMedia =
  directSelection.mediaType === 'none' && replySelection.mediaType !== 'none';
const selected = usesReplyMedia ? replySelection : directSelection;
const mediaSourceMessageId = usesReplyMedia
  ? String(repliedMessage.message_id ?? '')
  : messageId;

const capture = {
  capture_id: `cap_telegram_${chatId}_${messageId}`,
  channel: 'telegram',
  channel_message_id: messageId,
  captured_at: new Date(Number(message.date) * 1000).toISOString(),
  ingested_at: new Date().toISOString(),
  sender_id: String(message.from?.id ?? ''),
  raw_text: message.text ?? message.caption ?? '',
  media_type: selected.mediaType,
  media_original_ref: selected.media?.file_id ?? '',
  media_archive_url: '',
  transcript: '',
  processing_status: 'received',
  processing_error: '',
  extraction_summary: '',
  match_status: '',
  matched_product_id: '',
  match_confidence: '',
  chat_id: chatId,
  original_file_unique_id: selected.media?.file_unique_id ?? '',
  original_filename: selected.media?.file_name ?? '',
  mime_type: selected.media?.mime_type ?? '',
  media_source_message_id: mediaSourceMessageId,
  related_capture_id: usesReplyMedia
    ? `cap_telegram_${chatId}_${mediaSourceMessageId}`
    : '',
  relation_type: usesReplyMedia ? 'reply_to_media' : '',
};

return [{
  json: capture,
  binary: $input.item.binary ?? {},
  pairedItem: { item: 0 },
}];

const capture = $('Normalize Telegram Capture').item.json;
const downloaded = $('Download Telegram File').item;
const driveFileId = $json.id;
const binaryData = downloaded.binary?.data;

if (!binaryData) {
  throw new Error('Downloaded Telegram file is missing binary data.');
}

const extensionByMime = {
  'audio/ogg': '.ogg',
  'audio/mpeg': '.mp3',
  'audio/mp4': '.m4a',
  'audio/wav': '.wav',
  'audio/webm': '.webm',
  'image/jpeg': '.jpg',
  'image/png': '.png',
  'image/webp': '.webp',
};
const mimeType = String(capture.mime_type || binaryData.mimeType || '').trim();
const receivedName = String(
  capture.original_filename || binaryData.fileName || 'attachment',
).trim() || 'attachment';
const hasExtension = /\.[A-Za-z0-9]{2,5}$/.test(receivedName);
const normalizedFilename = hasExtension
  ? receivedName
  : `${receivedName}${extensionByMime[mimeType] || ''}`;
const normalizedBinary = {
  ...binaryData,
  fileName: normalizedFilename,
  mimeType,
};

return [{
  json: {
    ...capture,
    attachment_id: `att_${capture.capture_id}`,
    original_filename: normalizedFilename,
    mime_type: mimeType,
    drive_url: `https://drive.google.com/file/d/${driveFileId}/view`,
    media_archive_url:
      `https://drive.google.com/file/d/${driveFileId}/view`,
  },
  binary: {
    data: normalizedBinary,
  },
}];

const archived = $('Prepare Archived Capture').item.json;
const transcript = String(
  $json.transcript ?? archived.transcript ?? ''
).trim();

return [{
  json: {
    ...archived,
    transcript,
  },
}];

const archived = $('Prepare Archived Capture').item.json;
const transcript = String($json.text ?? $json.transcript ?? '').trim();

if (!transcript) {
  throw new Error('OpenAI returned an empty transcript.');
}

return [{
  json: {
    ...archived,
    transcript,
  },
}];

const rawText = String($json.raw_text ?? '').trim();
const transcript = String($json.transcript ?? '').trim();

const captureText = [
  rawText && `Typed text or caption:\n${rawText}`,
  transcript && `Voice transcript:\n${transcript}`,
].filter(Boolean).join('\n\n');

if (!captureText) {
  throw new Error('No text or transcript is available for extraction.');
}

return [{
  json: {
    ...$json,
    capture_text: captureText,
  },
}];

const capture = $('Prepare Extraction Input').first().json;
const response = $input.first().json;

const message = Array.isArray(response.output) ? response.output[0] : null;
const content = message?.content?.find((entry) => entry.type === 'output_text');
let extraction = content?.text;

if (typeof extraction === 'string') {
  extraction = JSON.parse(extraction);
}
if (!extraction || typeof extraction !== 'object' || Array.isArray(extraction)) {
  throw new Error('OpenAI output did not contain a structured extraction object');
}

const sourceText = String(
  capture.capture_text || capture.transcript || capture.raw_text || '',
);
const sourceLower = sourceText.toLocaleLowerCase();
const issues = [];
const originalExtraction = JSON.parse(JSON.stringify(extraction));

const reference =
  extraction.product_reference && typeof extraction.product_reference === 'object'
    ? { ...extraction.product_reference }
    : { mentioned_name: null, mentioned_part_numbers: [] };

if (reference.mentioned_name) {
  const name = String(reference.mentioned_name);
  if (!sourceLower.includes(name.toLocaleLowerCase())) {
    issues.push({
      code: 'unsupported_product_name',
      value: name,
      message: 'Product name was not stated exactly in the capture text',
    });
    reference.mentioned_name = null;
  }
}

const statedNumbers = Array.isArray(reference.mentioned_part_numbers)
  ? reference.mentioned_part_numbers.map(String)
  : [];
reference.mentioned_part_numbers = statedNumbers.filter((number) => {
  if (sourceText.includes(number)) return true;
  issues.push({
    code: 'unsupported_part_number',
    value: number,
    message: 'Part number was not present exactly in the capture text',
  });
  return false;
});

const claims = Array.isArray(extraction.claims)
  ? extraction.claims.map((claim) => ({ ...claim }))
  : [];
for (const claim of claims) {
  if (claim.claim_type !== 'part_number') continue;
  if (
    claim.structured_value == null &&
    reference.mentioned_part_numbers.length === 1
  ) {
    claim.structured_value = reference.mentioned_part_numbers[0];
  }
  if (
    claim.structured_value != null &&
    !sourceText.includes(String(claim.structured_value))
  ) {
    issues.push({
      code: 'unsupported_claim_part_number',
      value: String(claim.structured_value),
      message: 'Part-number claim was not supported by the capture text',
    });
    claim.structured_value = null;
    claim.evidence_class = 'unresolved';
  }
}

const validatedExtraction = {
  ...extraction,
  product_reference: reference,
  claims,
};

return [
  {
    json: {
      ...capture,
      extraction_raw: originalExtraction,
      extraction: validatedExtraction,
      extraction_summary: validatedExtraction.summary || '',
      extraction_validation_status: issues.length ? 'needs_review' : 'passed',
      extraction_validation_issues: issues,
    },
  },
];

const validated = $('Validate Extraction Evidence').first().json;
const catalogue = $input.first().json;
if (!Array.isArray(catalogue.products)) {
  throw new Error('Catalogue context is missing products');
}

return [
  {
    json: {
      capture: {
        capture_id: validated.capture_id,
        channel: validated.channel,
        channel_message_id: validated.channel_message_id,
        captured_at: validated.captured_at,
        ingested_at: validated.ingested_at,
        sender_id: validated.sender_id,
        raw_text: validated.raw_text || null,
        media_type: validated.media_type || 'none',
        media_original_ref: validated.media_original_ref || null,
        media_archive_url: validated.media_archive_url || null,
        transcript: validated.transcript || null,
        processing_status: validated.processing_status || 'received',
        processing_error: validated.processing_error || null,
      },
      extraction: validated.extraction,
      products: catalogue.products,
      catalogue_diagnostics: catalogue.diagnostics || {},
    },
  },
];

const result = $input.first().json;

if (!result.capture || !result.match || !result.rows) {
  throw new Error('Decision engine response is missing capture, match, or rows');
}

const routed = [
  {
    route: 'capture_inbox',
    match_key: 'capture_id',
    row: {
      ...result.capture,
      extraction_summary: result.extraction_summary || '',
      match_status: result.match.status || '',
      matched_product_id: result.match.product_id || '',
      match_confidence: result.match.confidence ?? '',
    },
  },
];

for (const row of result.rows.observations || []) {
  routed.push({ route: 'observation', match_key: 'observation_id', row });
}
for (const row of result.rows.part_numbers || []) {
  routed.push({ route: 'part_number', match_key: 'part_number_id', row });
}
for (const row of result.rows.review_queue || []) {
  routed.push({ route: 'review_queue', match_key: 'review_id', row });
}

return routed.map((item) => ({ json: item }));

const rows = (name) => $(name).all().map((item) => item.json);

return [{
  json: {
    products: rows('Read Products'),
    part_numbers: rows('Read Confirmed Part Numbers for Text'),
    image_evidence: [],
    visual_features: [],
  },
}];

const capture = $('Prepare Archived Capture').first().json;
const response = $input.first().json;

const message = Array.isArray(response.output) ? response.output[0] : null;
const content = message?.content?.find((entry) => entry.type === 'output_text');
let extraction = content?.text;

if (typeof extraction === 'string') {
  extraction = extraction.trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '');
  extraction = JSON.parse(extraction);
}
if (!extraction || typeof extraction !== 'object' || Array.isArray(extraction)) {
  throw new Error('OpenAI output did not contain a visual extraction object');
}

const allowedQuality = new Set(['insufficient', 'limited', 'usable', 'clear']);
const allowedViews = new Set([
  'full_item', 'label', 'connector', 'mounting_points', 'packaging', 'unknown',
]);
const allowedFeatureTypes = new Set([
  'shape', 'mounting', 'connector', 'dimension', 'material', 'color', 'marking', 'fitment',
]);
const requireArray = (key) => {
  if (!Array.isArray(extraction[key])) throw new Error(`${key} must be an array`);
};
const requireConfidence = (value, key) => {
  if (typeof value !== 'number' || value < 0 || value > 1) {
    throw new Error(`${key} confidence must be between 0 and 1`);
  }
};

if (typeof extraction.summary !== 'string' || !extraction.summary.trim()) {
  throw new Error('Visual extraction summary is required');
}
if (!allowedQuality.has(extraction.image_quality)) {
  throw new Error('Visual extraction returned an unsupported image_quality');
}
if (!allowedViews.has(extraction.view_type)) {
  throw new Error('Visual extraction returned an unsupported view_type');
}
for (const key of [
  'observed_part_numbers', 'label_texts', 'visual_features', 'fitment_terms', 'questions_needed',
]) requireArray(key);

for (const key of ['observed_part_numbers', 'label_texts']) {
  for (const [index, item] of extraction[key].entries()) {
    if (!item || typeof item.raw_text !== 'string' || !item.raw_text.trim()) {
      throw new Error(`${key}[${index}].raw_text is required`);
    }
    if (typeof item.region !== 'string' || !item.region.trim()) {
      throw new Error(`${key}[${index}].region is required`);
    }
    requireConfidence(item.confidence, `${key}[${index}]`);
  }
}
for (const [index, item] of extraction.visual_features.entries()) {
  if (!item || !allowedFeatureTypes.has(item.feature_type)) {
    throw new Error(`visual_features[${index}].feature_type is unsupported`);
  }
  if (typeof item.feature_name !== 'string' || !item.feature_name.trim()) {
    throw new Error(`visual_features[${index}].feature_name is required`);
  }
  if (typeof item.feature_value !== 'string' || !item.feature_value.trim()) {
    throw new Error(`visual_features[${index}].feature_value is required`);
  }
  requireConfidence(item.confidence, `visual_features[${index}]`);
}
for (const [index, item] of extraction.fitment_terms.entries()) {
  if (!item || typeof item.term !== 'string' || !item.term.trim()) {
    throw new Error(`fitment_terms[${index}].term is required`);
  }
  requireConfidence(item.confidence, `fitment_terms[${index}]`);
}
if (!extraction.questions_needed.every((item) => typeof item === 'string' && item.trim())) {
  throw new Error('questions_needed must contain only non-empty strings');
}

return [{ json: { ...capture, visual_extraction: extraction } }];

const rows = (name) => $(name).all().map((item) => item.json);

return [{
  json: {
    products: rows('Read Products for Image'),
    part_numbers: rows('Read Confirmed Part Numbers for Image'),
    image_evidence: rows('Read Accepted Image Evidence'),
    visual_features: rows('Read Reviewed Visual Features'),
  },
}];

const validated = $('Validate Visual Extraction').first().json;

const catalogue = $input.first().json;
if (!Array.isArray(catalogue.products) || !Array.isArray(catalogue.evidence_profiles)) {
  throw new Error('Catalogue context is missing products or evidence_profiles');
}

const capture = {
  capture_id: validated.capture_id,
  channel: validated.channel,
  channel_message_id: validated.channel_message_id,
  captured_at: validated.captured_at,
  ingested_at: validated.ingested_at,
  sender_id: validated.sender_id,
  raw_text: validated.raw_text || '',
  media_type: validated.media_type,
  media_original_ref: validated.media_original_ref || '',
  media_archive_url: validated.media_archive_url || '',
  transcript: validated.transcript || '',
  processing_status: validated.processing_status || 'received',
  processing_error: '',
};

return [{
  json: {
    capture_id: validated.capture_id,
    attachment_id: validated.attachment_id,
    captured_at: validated.captured_at,
    text_reference: {
      mentioned_name: null,
      confirmed_part_numbers: [],
    },
    visual_extraction: validated.visual_extraction,
    products: catalogue.products,
    evidence_profiles: catalogue.evidence_profiles,
    catalogue_diagnostics: catalogue.diagnostics || {},
    capture,
  },
}];

const result = $input.first().json;
const request = $('Prepare Image Decision Request').first().json;
const capture = request.capture;

if (!result.match || !result.rows || !capture) {
  throw new Error('Image decision response is missing match, rows, or capture context');
}

const routed = [{
  route: 'capture_inbox',
  row: {
    ...capture,
    processing_status: result.match.status === 'matched' ? 'processed' : 'needs_review',
    extraction_summary: result.visual_summary || '',
    match_status: result.match.status || '',
    matched_product_id: result.match.product_id || '',
    match_confidence: result.match.confidence ?? '',
  },
}];

for (const row of result.rows.image_evidence || []) {
  routed.push({ route: 'image_evidence', row });
}
for (const row of result.rows.visual_features || []) {
  routed.push({ route: 'visual_feature', row });
}
for (const row of result.rows.review_queue || []) {
  routed.push({ route: 'review_queue', row });
}

return routed.map((item) => ({ json: item }));

const row = $input.first().json;
if (String(row.status || '').toLowerCase() !== 'open') return [];

const parseList = (value) => {
  if (Array.isArray(value)) return value;
  if (typeof value !== 'string' || !value.trim()) return [];
  try {
    const parsed = JSON.parse(value);
    return Array.isArray(parsed) ? parsed : [];
  } catch {
    return [];
  }
};

const candidates = parseList(row.candidate_matches).slice(0, 3);
const questions = parseList(row.questions_needed).slice(0, 3);
const lines = [
  'Review needed',
  `Review ID: ${row.review_id}`,
  `Reason: ${row.reason || 'identity requires confirmation'}`,
];
if (candidates.length) {
  lines.push('', 'Candidates:');
  for (const [index, candidate] of candidates.entries()) {
    const score = Number(candidate.score);
    const percentage = Number.isFinite(score)
      ? ` — ${Math.round(score * 100)}%`
      : '';
    lines.push(
      `${index + 1}. ${candidate.canonical_name || 'Unnamed product'} (${candidate.product_id})${percentage}`,
    );
  }
}
if (questions.length) {
  lines.push('', 'Check:');
  for (const question of questions) lines.push(`- ${question}`);
}
lines.push(
  '',
  'Reply to this message with one decision:',
  'link PRODUCT_ID',
  'link PRODUCT_ID --accept-image',
  'new "PRODUCT NAME"',
  'reject',
  '',
  'Only add --pn=PART_NUMBER after checking the physical label.',
);
return [{ json: { ...row, notification_text: lines.join('\n') } }];

